CheatEntry.AssemblerScript:
[ENABLE] // Tested executable's update prologue and activation entry. assert("PMA_W32_M.exe"+185590,81 EC A0 00 00 00 53 55 56 8B E9) assert("PMA_W32_M.exe"+17B270,83 EC 08 E9 93 5D EC FF) alloc(PMW3GiveMemory,0x1000,"PMA_W32_M.exe"+185590) label(PMW3GiveCode) label(PMW3GiveOriginal) label(PMW3GiveUnlock) label(PMW3GiveInvalid) label(PMW3GiveRequest) label(PMW3GiveBusy) registersymbol(PMW3GiveRequest)
PMW3GiveMemory: PMW3GiveRequest: dd FFFFFFFF PMW3GiveBusy: dd 0
PMW3GiveCode: pushfd pushad
// Only accept the player resolved by the tested pointer chain. mov eax,["PMA_W32_M.exe"+3CDF3C] test eax,eax je PMW3GiveOriginal mov eax,[eax+24] test eax,eax je PMW3GiveOriginal cmp eax,ecx jne PMW3GiveOriginal
// Original update sets this field to 1 after its initial setup. cmp dword ptr [ecx+7D4],0 je PMW3GiveOriginal cmp dword ptr [PMW3GiveRequest],FFFFFFFF je PMW3GiveOriginal
// Avoid dispatching recursively or concurrently through this hook. mov edx,1 xchg dword ptr [PMW3GiveBusy],edx test edx,edx jne PMW3GiveOriginal
// Consume once. Unsigned comparison rejects negatives as well as >= 6. mov eax,FFFFFFFF xchg dword ptr [PMW3GiveRequest],eax cmp eax,5 ja PMW3GiveInvalid
// Preserve the caller's x87/SSE state in a 16-byte-aligned 512-byte area. // EBX is callee-saved by the game's activation routine. mov ebx,esp sub esp,210 and esp,FFFFFFF0 fxsave [esp] fninit fldcw word ptr [esp] cld
// thiscall: ECX = player, [ESP+4] = ID at function entry. // Activation returns with RET 4, so do not adjust ESP after the call. push eax call "PMA_W32_M.exe"+17B270
fxrstor [esp] mov esp,ebx jmp PMW3GiveUnlock
PMW3GiveInvalid: PMW3GiveUnlock: mov dword ptr [PMW3GiveBusy],0 PMW3GiveOriginal: popad popfd // Replay the entire overwritten instruction, then resume the update. sub esp,A0 jmp "PMA_W32_M.exe"+185596
"PMA_W32_M.exe"+185590: jmp PMW3GiveCode nop
[DISABLE] PMW3GiveRequest: dd FFFFFFFF "PMA_W32_M.exe"+185590: db 81 EC A0 00 00 00 unregistersymbol(PMW3GiveRequest) // Intentionally retain this small allocation until the process exits: // a thread already executing the hook must not return into freed memory. // Each re-enable allocates another 4 KiB.

[ENABLE] // EAX is set to 1 here and stays 1 until the flag store below. assert("PMA_W32_M.exe"+12EC98,B8 01 00 00 00 89 47 14) assert("PMA_W32_M.exe"+12ECE3,39 AE E0 07 00 00 89 1D 9C DD 7C 00 75 13) assert("PMA_W32_M.exe"+15BA6A,39 1D 9C DD 7C 00 75 06 FF 87 D0 00 00 00)
// Change only the source register: mov [007CDD9C],ebx -> mov [007CDD9C],eax. // EBX=0; EAX=1. MOV preserves the flags used by the following JNE. "PMA_W32_M.exe"+12ECEA: db 05
// Also enable the flag immediately, without waiting for state entry. "PMA_W32_M.exe"+3CDD9C: dd 00000001
[DISABLE] assert("PMA_W32_M.exe"+12ECE9,89 05 9C DD 7C 00) "PMA_W32_M.exe"+12ECEA: db 1D "PMA_W32_M.exe"+3CDD9C: dd 00000000

// Bypass only normal RevRoll timer expiry. Native input/contact stops remain. // Elapsed time keeps advancing for the airborne speed ramp. // Enable/disable while the process is paused and Pac-Man is idle. [ENABLE] assert("PMA_W32_M.exe"+15C8A6,D9 45 14 D8 1D 1C D2 75 00 DF E0 F6 C4 05 0F 8B AC 03 00 00) assert("PMA_W32_M.exe"+15C8BA,8B 83 30 04 00 00 8B 48 48 8B 11 39 B2 40 05 00 00 0F 85 95 03 00 00) assert("PMA_W32_M.exe"+15CF9F,A1 B0 DD 7C 00 85 C0 74 18 D9 45 14 D8 1D 1C D2 75 00 DF E0 F6 C4 05 7A 08) assert("PMA_W32_M.exe"+15CF3D,53 8B CD E8 BB 20 FD FF) assert("PMA_W32_M.exe"+15CFC0,A1 EC 9C 79 00 8B 8B 30 04 00 00 69 C0 08 01 00 00)
"PMA_W32_M.exe"+15C8B4: // Original JNP to StopRolling when remaining time is negative. db 90 90 90 90 90 90 "PMA_W32_M.exe"+15CFA6: // Always take the native 'no airborne timeout' route to the input check. db EB 18
[DISABLE] "PMA_W32_M.exe"+15C8B4: db 0F 8B AC 03 00 00 "PMA_W32_M.exe"+15CFA6: db 74 18
